    List<PartAttributeDeformObjectBuilder>? deforms,
    List<int>? drawOrder,
    List<DrawBatchObjectBuilder>? drawBatches,
    List<int>? maskIndices,
  })
      : _parts = parts,
        _cells = cells,
        _partsColor = partsColor,
        _shaders = shaders,
        _vertices = vertices,
        _deforms = deforms,
        _drawOrder = drawOrder,
        _drawBatches = drawBatches,
        _maskIndices = maskIndices;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? partsOffset = _parts == null ? null
        : fbBuilder.writeListOfStructs(_parts!);
    final int? cellsOffset = _cells == null ? null
        : fbBuilder.writeListOfStructs(_cells!);
    final int? partsColorOffset = _partsColor == null ? null
        : fbBuilder.writeListOfStructs(_partsColor!);
    final int? shadersOffset = _shaders == null ? null
        : fbBuilder.writeListOfStructs(_shaders!);
    final int? verticesOffset = _vertices == null ? null
        : fbBuilder.writeListOfStructs(_vertices!);
    final int? deformsOffset = _deforms == null ? null
        : fbBuilder.writeList(_deforms!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? drawOrderOffset = _drawOrder == null ? null
        : fbBuilder.writeListUint16(_drawOrder!);
    final int? drawBatchesOffset = _drawBatches == null ? null
        : fbBuilder.writeListOfStructs(_drawBatches!);
    final int? maskIndicesOffset = _maskIndices == null ? null
        : fbBuilder.writeListUint16(_maskIndices!);
    fbBuilder.startTable(9);
    fbBuilder.addOffset(0, partsOffset);
    fbBuilder.addOffset(1, cellsOffset);
    fbBuilder.addOffset(2, partsColorOffset);
    fbBuilder.addOffset(3, shadersOffset);
    fbBuilder.addOffset(4, verticesOffset);
    fbBuilder.addOffset(5, deformsOffset);
    fbBuilder.addOffset(6, drawOrderOffset);
    fbBuilder.addOffset(7, drawBatchesOffset);
    fbBuilder.addOffset(8, maskIndicesOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
